create table Album (album_id integer generated by default as identity, master_id integer, rating_average float(53), rating_count integer, release_id integer unique, year integer, title varchar(500), wikipedia_url varchar(500), companies TEXT, coverartarchive_thumb varchar(255), date_added varchar(255), date_changed varchar(255), extra_artists TEXT, genres TEXT, images TEXT, labels TEXT, musicbrainz_uuid varchar(255), raw_wikipedia_url TEXT, release_format_description varchar(255), release_type varchar(255), released varchar(255), released_formatted varchar(255), styles TEXT, tracklist TEXT, videos TEXT, wikidata_id varchar(255), wikipedia_data TEXT, youtube_video_id_for_thumbnail varchar(255), primary key (album_id));
create table AlbumContainsArtist (album_id integer not null, artist_id integer not null, is_main integer not null, primary key (album_id, artist_id));
create table AppUser (created_at timestamp(6), updated_at timestamp(6), role varchar(50), firebase_uid varchar(128) not null, display_name varchar(255), email varchar(255) not null, primary key (firebase_uid));
create table Artist (artist_id integer generated by default as identity, artist_rank integer, discogs_id integer, instrument_id integer, image_author varchar(1000), image_source_url varchar(1000), thumbnail_url varchar(1000), artist_fullname varchar(255), artist_name varchar(255), artist_surname varchar(255), bands_under_this_artist TEXT, image_license varchar(255), musicbrainz_uuid varchar(255), name_variations TEXT, spotify_playlist_id varchar(255), wikidata_id varchar(255), wikipedia_data TEXT, wikipedia_url varchar(255), primary key (artist_id));
create table Duration (duration_id integer generated by default as identity, duration_description varchar(255), duration_name varchar(255), primary key (duration_id));
create table Instrument (instrument_id integer generated by default as identity, instrument_name varchar(255), name_variations TEXT, primary key (instrument_id));
create table Quote (artist_id integer, quote_id integer generated by default as identity, video_id integer, quote_text varchar(255), primary key (quote_id));
create table song (album_id integer, main_artist_id integer not null, song_id integer generated by default as identity, duration varchar(255), related_artists varchar(255), song_title varchar(255) not null, video_availability varchar(255), writer TEXT, yt_videoid varchar(255), primary key (song_id));
create table Type (type_id integer generated by default as identity, type_name varchar(255), primary key (type_id));
create table Video (duration_id integer, type_id integer, video_id integer generated by default as identity, location_id varchar(255), video_availability varchar(255), video_duration varchar(255), video_name varchar(255), video_path varchar(255), primary key (video_id));
create table VideoContainsArtist (artist_id integer not null, video_id integer not null, primary key (artist_id, video_id));
alter table if exists AlbumContainsArtist add constraint FK1p0hrgrf9ua0qk76imruuphhg foreign key (album_id) references Album;
alter table if exists AlbumContainsArtist add constraint FKao6lm3jn1i6bo46coc239sska foreign key (artist_id) references Artist;
alter table if exists Artist add constraint FK_instrument_id foreign key (instrument_id) references Instrument;
alter table if exists Quote add constraint FK_artist_id foreign key (artist_id) references Artist;
alter table if exists Quote add constraint FK_video_id foreign key (video_id) references Video;
alter table if exists song add constraint FKkiwqb14hicaeaysy6smvcrl5d foreign key (album_id) references Album;
alter table if exists song add constraint FKnji1r97r1nsr6jafcfe8ltldy foreign key (main_artist_id) references Artist;
alter table if exists Video add constraint FK_duration_id foreign key (duration_id) references Duration;
alter table if exists Video add constraint FK_type_id foreign key (type_id) references Type;
alter table if exists VideoContainsArtist add constraint FKnmfr018s4orfn4qwba2bflha1 foreign key (artist_id) references Artist;
alter table if exists VideoContainsArtist add constraint FK92qk8g1pflug8kkpngruh0lj6 foreign key (video_id) references Video;
